  --color-surface:   #ffffff;
  --color-border:    #e4e4ec;
  --color-text:      #1a1a2e;
  --color-muted:     #6b6b80;
  --color-primary:   #6366f1;
  --color-primary-hover: #4f52e0;
  --color-danger:    #dc2626;
  --color-danger-hover: #b91c1c;
  --color-danger-bg: #fef2f2;
  --radius-sm:       6px;
  --radius-md:       12px;
  --radius-lg:       16px;
  --shadow-sm:       0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:       0 4px 16px rgba(0,0,0,.08), 0 1px 4px rgba(0,0,0,.04);
  --shadow-lg:       0 20px 60px rgba(0,0,0,.16), 0 4px 16px rgba(0,0,0,.08);
  --transition:      150ms ease;
}

html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100dvh;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Screen-reader only ───────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ───────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 10;
  box-shadow: var(--shadow-sm);
}
.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--color-text);
  letter-spacing: -.01em;
}
.site-header nav ul {
  list-style: none;
  display: flex;
  gap: .25rem;
}
.site-header nav a {
  display: block;
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  color: var(--color-muted);
  text-decoration: none;
  font-size: .9rem;
  font-weight: 500;
  transition: background var(--transition), color var(--transition);
}
.site-header nav a:hover,
.site-header nav a:focus-visible {
  background: var(--color-bg);
  color: var(--color-text);
}
.site-header nav a[aria-current="page"] {
  color: var(--color-primary);
  background: #eef2ff;
}

/* ── Main layout ──────────────────────────────────────────────── */
#main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}
.preview-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1.5rem;
  align-items: start;
}
@media (max-width: 800px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ── Image panel ──────────────────────────────────────────────── */
.image-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.image-frame {
  aspect-ratio: 4/3;
  background: #0a0a14;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ── Metadata panel ───────────────────────────────────────────── */
.meta-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 76px;
}
.meta-inner { padding: 1.5rem; }

.image-title {
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}
.image-meta {
  margin-top: .35rem;
  font-size: .82rem;
  color: var(--color-muted);
}

/* ── Detail list ──────────────────────────────────────────────── */
.detail-list {
  margin-top: 1.25rem;
  border-top: 1px solid var(--color-border);
  padding-top: 1rem;
  display: grid;
  gap: .6rem;
}
.detail-list > div {
  display: flex;
  justify-content: space-between;
  gap: .5rem;
  font-size: .875rem;
}
.detail-list dt { color: var(--color-muted); }
.detail-list dd { font-weight: 500; text-align: right; }

/* ── Action row ───────────────────────────────────────────────── */
.action-row {
  margin-top: 1.5rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  gap: .6rem;
}

/* ── Buttons ──────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .45rem;
  padding: .55rem 1rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  line-height: 1;
}
.btn:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.btn-secondary {
  background: var(--color-surface);
  color: var(--color-text);
  border-color: var(--color-border);
  box-shadow: var(--shadow-sm);
}
.btn-secondary:hover {
  background: var(--color-bg);
  border-color: #c4c4d4;
}

.btn-danger {
  background: var(--color-danger);
  color: #fff;
}
.btn-danger:hover { background: var(--color-danger-hover); }
.btn-danger:focus-visible { outline-color: var(--color-danger); }

/* ── Dialog ───────────────────────────────────────────────────── */
dialog {
  border: none;
  border-radius: var(--radius-lg);
  padding: 0;
  box-shadow: var(--shadow-lg);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  background: var(--color-surface);
}

