dialog:not([open]) { display: none; }

dialog::backdrop {
  background: rgba(10, 10, 20, .55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

/* Entrance animation */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: dialog-in 200ms ease both;
  }
  @keyframes dialog-in {
    from { opacity: 0; transform: translateY(8px) scale(.97); }
    to   { opacity: 1; transform: translateY(0)   scale(1); }
  }
}

.dialog-inner {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: .75rem;
}

.dialog-icon { flex-shrink: 0; }

.dialog-heading {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -.02em;
}

.dialog-body {
  font-size: .925rem;
  color: var(--color-muted);
  line-height: 1.6;
  max-width: 320px;
}
.dialog-body strong { color: var(--color-text); font-weight: 600; }

.dialog-actions {
  display: flex;
  gap: .75rem;
  margin-top: .5rem;
  width: 100%;
}
.dialog-actions .btn { flex: 1; }

/* ── Forced colors (high-contrast) ───────────────────────────── */
@media (forced-colors: active) {
  .btn { forced-color-adjust: auto; }
  dialog { border: 2px solid ButtonText; }
}

/* ── Reflow: single-column on narrow viewports ────────────────── */
@media (max-width: 400px) {
  .dialog-inner { padding: 1.5rem 1.25rem; }
  .dialog-actions { flex-direction: column-reverse; }
}
