(function () {
  'use strict';

  const dialog       = document.getElementById('delete-dialog');
  const trigger      = document.getElementById('delete-trigger');
  const cancelBtn    = document.getElementById('cancel-btn');
  const confirmBtn   = document.getElementById('confirm-delete-btn');
  const statusRegion = document.getElementById('status');

  // Open the dialog
  trigger.addEventListener('click', () => {
    dialog.showModal();
  });

  // Cancel — close without action
  cancelBtn.addEventListener('click', () => {
    dialog.close('cancel');
  });

  // Confirm — close and announce deletion
  confirmBtn.addEventListener('click', () => {
    dialog.close('delete');
  });

  // Handle the result after closing
  dialog.addEventListener('close', () => {
    if (dialog.returnValue === 'delete') {
      // Announce to screen readers
      statusRegion.textContent = 'Image deleted from your library.';

      // Visual feedback: disable trigger to reflect deleted state
      trigger.disabled = true;
      trigger.textContent = 'Deleted';

      // Clear the status message after a delay so it can re-announce if needed
      setTimeout(() => { statusRegion.textContent = ''; }, 5000);
    }

    // Focus returns to trigger automatically (native <dialog> behaviour).
    // Guard: if the trigger is gone from the DOM, focus the <main> element.
    if (!document.contains(trigger)) {
      const main = document.getElementById('main');
      if (main) { main.focus(); }
    }
  });
}());

