const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const dir = '/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-vanilla-js--style-modern/claude-sonnet-4.6__s3';
const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Patch asset paths to be absolute so CSS/JS loads
  const patched = html
    .replace('href="styles.css"', `href="file://${dir}/styles.css"`)
    .replace('src="app.js"',     `src="file://${dir}/app.js"`);

  await page.setContent(patched, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Test 1: closed (default) state
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Test 2: open dialog state
  await page.evaluate(() => document.getElementById('delete-dialog').showModal());
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const fmt = v => ({ id: v.id, impact: v.impact, tags: v.tags.filter(t => t.startsWith('wcag') || t === 'best-practice'), targets: v.nodes.map(n => n.target) });
  const all = [...r1.violations, ...r2.violations];
  const seen = new Set();
  const deduped = all.filter(v => { if (seen.has(v.id)) return false; seen.add(v.id); return true; });

  const wcag = deduped.filter(v => !v.tags.includes('best-practice'));
  const bp   = deduped.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
EOF
